// Static game data for Marvel Champions (French): core set and the Green Goblin scenario pack.
// cards.json and precons.json are generated by scripts/build-data.py; bouffon-vert.json is
// written by hand from the printed cards (ids "gob-<card number>").
//
// Card definition: {id, n name, t type, f faction, s set, q copies, l landscape,
//   st stage, hp, hs hand size, th threshold, esc acceleration (number or "X"), bth starting threat,
//   bn / bt / bhs / bst back side name, type, hand size, stage, tr / btr traits (front / back, villains
//   and minions of the scenario packs only), dir image folder under public/cards/}
import CORE from '../data/cards.json'
import GREEN_GOBLIN from '../data/bouffon-vert.json'
import PRECONS from '../data/precons.json'

export { PRECONS }

export const PACKS = [
  { id: 'core', name: 'Boîte de base', dir: 'base', cards: CORE },
  { id: 'green_goblin', name: 'Le Bouffon Vert', dir: 'bouffon vert', cards: GREEN_GOBLIN }
]

/** Every card definition, tagged with the image folder of its pack. */
export const DEFS = PACKS.flatMap(p => p.cards.map(d => ({ ...d, dir: p.dir })))

/** Card id (OCTGN GUID for the core set) → card definition */
export const BY_ID = Object.fromEntries(DEFS.map(d => [d.id, d]))

